// Entities generated by USDStageComponent are missing from Scene.performQuery
// and send no ComponentEvents, although they render and `children` reaches them.
//
//   swift run USDKitQueryRepro
//
// Apple frameworks only. Prints the counts and exits.

import AppKit
import RealityKit
import SwiftUI
import USDKit

let usda = """
#usda 1.0
(
    defaultPrim = "World"
    upAxis = "Y"
    metersPerUnit = 1
)
def Xform "World"
{
    def Cube "Box"
    {
        double size = 0.3
    }
    def Sphere "Ball"
    {
        double radius = 0.15
        double3 xformOp:translate = (0.5, 0, 0)
        uniform token[] xformOpOrder = ["xformOp:translate"]
    }
}
"""

@MainActor final class Counter { var didAdd = 0; var subscription: EventSubscription? }

func descendants(_ entity: Entity) -> [Entity] { entity.children.flatMap { [$0] + descendants($0) } }

struct ReproView: View {
	var body: some View {
		RealityView { content in
			let url = FileManager.default.temporaryDirectory.appendingPathComponent("USDKitQueryRepro.usda")
			try? usda.write(to: url, atomically: true, encoding: .utf8)

			let stageEntity = Entity()
			stageEntity.name = "stage"
			content.add(stageEntity)

			let counter = Counter()
			counter.subscription = content.subscribe(to: ComponentEvents.DidAdd.self, componentType: ModelComponent.self) { _ in
				counter.didAdd += 1
			}

			let control = ModelEntity(mesh: .generateBox(size: 0.1))
			control.name = "control"
			content.add(control)

			do {
				let stage = try USDStage.open(url)
				stageEntity.components[USDStageComponent.self] = await USDStageComponent(stage, timeCode: .default)
				let result = await USDStageComponent.waitForRenderCompletion(on: stageEntity)
				print("render status: \(result.status)")
			} catch {
				print("failed to open stage: \(error)")
				exit(1)
			}
			try? await Task.sleep(for: .seconds(1))

			let scene = stageEntity.scene!
			let queried = scene.performQuery(EntityQuery(where: .has(ModelComponent.self))).map { $0 }
			let generated = descendants(stageEntity).filter { $0.components.has(ModelComponent.self) }
			print("ModelComponent entities generated under the stage (via children): \(generated.count)")
			print("  of those, returned by performQuery(.has(ModelComponent.self)): \(generated.filter { e in queried.contains { $0 === e } }.count)")
			print("control ModelEntity returned by performQuery: \(queried.contains { $0 === control })")
			print("stage entity returned by performQuery(.has(USDStageComponent.self)): \(scene.performQuery(EntityQuery(where: .has(USDStageComponent.self))).contains { $0 === stageEntity })")
			print("ComponentEvents.DidAdd<ModelComponent> received: \(counter.didAdd) (control: 1 expected, plus one per generated mesh)")
			exit(0)
		}
		.frame(width: 400, height: 300)
	}
}

@main struct ReproApp: App {
	init() {
		NSApplication.shared.setActivationPolicy(.regular)
		NSApplication.shared.activate()
	}
	var body: some SwiftUI.Scene { WindowGroup { ReproView() } }
}
